import React, { useState, useRef } from "react";
import "./Accordion.css";

const data = [
  {
    question: "How do I verify my email?",
    answer: `Click the link in the verification email from verify@codepen.io (be sure to check your spam folder or other email tabs if it's not in your inbox).
    Or, send an email with the subject "Verify" to verify@codepen.io from the email address you use for your CodePen account.`
  },
  {
    question: "My Pen loads infinitely or crashes the browser.",
    answer: `It's likely an infinite loop in JavaScript that we could not catch. To fix, add ?turn_off_js=true to the end of the URL.`
  },
  {
    question: "How do I contact the creator of a Pen?",
    answer: `You can leave a comment on any public Pen.`
  },
  {
    question: "What version of [library] does CodePen use?",
    answer: `We have our current list of library versions here: https://codepen.io/versions`
  },
  {
    question: "What are forks?",
    answer: `A fork is a complete copy of a Pen or Project that you can save to your own account and modify.`
  }
];

export default function Accordion() {
  const [activeIndex, setActiveIndex] = useState(null);
  const answerRefs = useRef([]);

  const toggleAccordion = (index) => {
    setActiveIndex(index === activeIndex ? null : index);
  };

  return (
    <div className="faq_wrapper">
      {data.map((item, index) => (
        <div className="faq_container" key={index}>
          <div
            className={`question ${activeIndex === index ? "active" : ""}`}
            onClick={() => toggleAccordion(index)}
          >
            {item.question}
          </div>
          <div
            className="answer_wrapper"
            ref={(el) => (answerRefs.current[index] = el)}
            style={{
              maxHeight:
                activeIndex === index
                  ? `${answerRefs.current[index]?.scrollHeight}px`
                  : "0px"
            }}
          >
            <div className="answer">{item.answer}</div>
          </div>
        </div>
      ))}
    </div>
  );
}
