import { Button, Button2, Cardbutton } from "../components/button";
import { Link } from "react-router-dom";
import React, { useEffect, useRef } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import "./adventure.css";

// import adventure

import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCalendar } from "@fortawesome/free-solid-svg-icons";


gsap.registerPlugin(ScrollTrigger);

function Adventure({advImg, advHeading, advPara, advDurations, advPrice}){


        // adventure section 
    const advRef = useRef(null);

useEffect(() => {
  let ctx = gsap.context(() => {
    gsap.utils.toArray(".adventure_inner_card").forEach((card) => {
      gsap.to(card, {
        y: -15,
        scale: 1.04,
        ease: "none",
        duration: 0.2,
        scrollTrigger: {
          trigger: card,
          start: "top center",
          end: "bottom center",
          toggleActions: "play reverse play reverse",
        },
      });
    });
  }, advRef);

  return () => ctx.revert();
}, []);


    return(
                    <div className="col-lg-12 mt-5" >
                        <div className="row packages_adv" ref={advRef}>
                            <div className="rafting-parent col-lg-12" >
                                <div className="row adventure_inner_card" >
                                    <div className="col-lg-6 col-md-6 rafting">
                                        <img src={advImg} alt="" />
                                    </div>
                                    <div className="col-lg-6 col-md-6 rafting_detail d-flex align-items-center">
                                        <div className="inner_detail_adv">
                                            <h2 className="card_headings">{advHeading}</h2>
                                            <p className="paragraphs">{advPara}</p>
                                            <p className="time">
                                                <FontAwesomeIcon className="icons" icon={faCalendar} />
                                                {advDurations}</p>
                                            <div className="row align-items-center mt-2">
                                                <div className="col-lg-6 col-md-6 col-6">
                                                    <p className="start_from">Starting from <br /> <span className="card_price">&#8377;{advPrice}</span></p>
                                                </div>
                                                <div className="col-lg-6 col-md-6 col-6">
                                                    <Link>
                                                        <Cardbutton label="View Tour" />
                                                    </Link>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
    )
}



export default Adventure;