    useEffect(() => {
        const boxes = document.querySelectorAll(".services_boxes");

        const activeMap = new Map();

        if (window.innerWidth < 767) {

            boxes.forEach((box) => {
                const heading = box.querySelector(".fancy-hover");
                const button = box.querySelector(".buttons2");

                gsap.set(heading, { "--after-width": "0%" });
                gsap.set(button, { opacity: 0, y: 0 });

                const tl = gsap.timeline({ paused: true, defaults: { ease: "power2.out" } });

                tl.to(heading, {
                    "--after-width": "100%",
                    duration: 0.4
                });

                tl.to(button, {
                    opacity: 1,
                    y: -20,
                    duration: 0.3
                }, "<");

                activeMap.set(box, tl);

                ScrollTrigger.create({
                    trigger: box,
                    start: "top 45%",
                    end: "bottom 45%",
                    onEnter: () => {
                        resetAllExcept(box);
                        tl.play();
                    },
                    onLeave: () => tl.reverse(),
                    onEnterBack: () => {
                        resetAllExcept(box);
                        tl.play();
                    },
                    onLeaveBack: () => tl.reverse(),
                    // markers: true,
                });

                box.addEventListener("click", () => {
                    resetAllExcept(box);
                    tl.play();
                });
            });

            function resetAllExcept(currentBox) {
                activeMap.forEach((timeline, box) => {
                    if (box !== currentBox) {
                        timeline.reverse();
                    }
                });
            }

        } else {

            const allVideos = document.querySelectorAll(".service_image video");

            boxes.forEach((box) => {
                const videoId = box.getAttribute("data-img");
                const targetVideo = document.getElementById(videoId);

                box.addEventListener("mouseenter", () => {
                    gsap.to(allVideos, {
                        opacity: 0,
                        x: -200,
                        ease: "power2.out",
                        duration: 0.3
                    });

                    gsap.to(targetVideo, {
                        opacity: 1,
                        x: 0,
                        duration: 0.4,
                        ease: "power2.out"
                    });
                });

                box.addEventListener("mouseleave", () => {
                    gsap.to(targetVideo, {
                        opacity: 0,
                        x: -100,
                        duration: 0.3,
                        ease: "power2.out"
                    });
                });
            });
        }

        return () => {
            ScrollTrigger.getAll().forEach(trigger => trigger.kill());

            boxes.forEach((box) => {
                box.replaceWith(box.cloneNode(true));
            });
        };
    }, []);




